# The music page is an ordinary <img>. Canvas is used only as a transparent stroke layer.
HTML=r"""
<div id="rv28">
 <div class="toolbar"><button id="viewOverlay">Mask</button><button id="viewPage">Original</button><button id="viewMask">Mask only</button><button id="viewConfidence">Confidence</button></div>
 <div class="toolbar"><button id="modeAdd">ADD</button><button id="modeErase">ERASE</button><button id="modeNone" class="active">NAVIGATE</button><button id="undo">Undo</button><button id="redo">Redo</button><label>Brush <input id="brush" type="range" min="2" max="60" value="14"></label></div>
 <div id="imageScroller"><div id="imageStage"><img id="pageImage" draggable="false"><canvas id="strokeLayer"></canvas></div></div>
 <button id="authorise" class="primary">Authorise reviewed mask</button>
</div>
"""
JS=r"""async(...args)=>{const $=x=>document.getElementById(x),img=$('pageImage'),cv=$('strokeLayer'),cx=cv.getContext('2d');let page=null,mode='none',strokes=[],redo=[],active=null;function field(){return document.querySelector('#action-bridge textarea')||document.querySelector('#action-bridge input')}function setMode(m){mode=m;['Add','Erase','None'].forEach(x=>$('mode'+x).classList.toggle('active',x.toLowerCase()===m))}function redraw(){cx.clearRect(0,0,cv.width,cv.height);for(const s of strokes){cx.strokeStyle=s.mode==='add'?'rgba(0,80,255,.72)':'rgba(0,200,70,.72)';cx.lineWidth=s.brush;cx.lineCap='round';cx.lineJoin='round';cx.beginPath();s.points.forEach((p,i)=>i?cx.lineTo(p[0],p[1]):cx.moveTo(p[0],p[1]));cx.stroke()}}function view(src){if(src)img.src=src}async function ingest(raw){page=JSON.parse(raw);img.onload=()=>{cv.width=page.width;cv.height=page.height;cv.style.width=img.clientWidth+'px';cv.style.height=img.clientHeight+'px';redraw()};img.style.width=page.width+'px';img.style.height=page.height+'px';view(page.overlay_url);strokes=[];redo=[];setMode('none')}window.hitlIngest=ingest;$('viewOverlay').onclick=()=>view(page?.overlay_url);$('viewPage').onclick=()=>view(page?.page_url);$('viewMask').onclick=()=>view(page?.mask_url);$('viewConfidence').onclick=()=>view(page?.confidence_url);$('modeAdd').onclick=()=>setMode('add');$('modeErase').onclick=()=>setMode('erase');$('modeNone').onclick=()=>setMode('none');$('undo').onclick=()=>{if(strokes.length)redo.push(strokes.pop());redraw()};$('redo').onclick=()=>{if(redo.length)strokes.push(redo.pop());redraw()};function pt(e){const r=cv.getBoundingClientRect();return [(e.clientX-r.left)*cv.width/r.width,(e.clientY-r.top)*cv.height/r.height]}cv.onpointerdown=e=>{if(mode==='none')return;e.preventDefault();cv.setPointerCapture(e.pointerId);active={mode:mode,brush:+$('brush').value,points:[pt(e)]}};cv.onpointermove=e=>{if(!active)return;e.preventDefault();active.points.push(pt(e));redraw();cx.strokeStyle=active.mode==='add'?'rgba(0,80,255,.72)':'rgba(0,200,70,.72)';cx.lineWidth=active.brush;cx.lineCap='round';cx.beginPath();active.points.forEach((p,i)=>i?cx.lineTo(p[0],p[1]):cx.moveTo(p[0],p[1]));cx.stroke()};cv.onpointerup=e=>{if(active){strokes.push(active);active=null;redo=[];redraw()}};cv.onpointercancel=cv.onpointerup;cv.oncontextmenu=e=>e.preventDefault();$('authorise').onclick=()=>{const h=field();if(!h||!page)return;const payload=JSON.stringify({strokes:strokes,preview_width:page.width,preview_height:page.height});const proto=h.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype;Object.getOwnPropertyDescriptor(proto,'value').set.call(h,payload);h.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText'}));h.dispatchEvent(new Event('change',{bubbles:true}))};setMode('none');return []}"""
CSS=r""".bridge-offscreen{position:fixed!important;left:-10000px!important;width:1px!important;height:1px!important;opacity:0!important}.toolbar{display:flex;gap:6px;flex-wrap:wrap;margin:6px 0}.toolbar button,#authorise{min-height:42px;padding:7px 11px}.toolbar button.active{background:#205493;color:white}.primary{background:#205493;color:white}#imageScroller{width:100%;max-height:72vh;overflow:auto;background:#aaa;-webkit-overflow-scrolling:touch}#imageStage{position:relative;width:max-content;line-height:0}#pageImage{display:block;max-width:none;user-select:none;-webkit-user-drag:none}#strokeLayer{position:absolute;left:0;top:0;touch-action:none;-webkit-touch-callout:none;user-select:none}#modeNone.active~*{}"""
